+import { LINEAR_UNITS, TEMPERATURE_UNITS, type LinearUnit } from "./units.ts";
+
+type TemperatureSymbol = (typeof TEMPERATURE_UNITS)[number];
+
+interface TemperatureUnit {
+  kind: "temperature";
+  symbol: TemperatureSymbol;
+}
+
+type ResolvedUnit = LinearUnit | TemperatureUnit;
+
+function resolve(symbol: string): ResolvedUnit | undefined {
+  const linear = LINEAR_UNITS[symbol];
+  if (linear !== undefined) return linear;
+  for (const temperature of TEMPERATURE_UNITS) {
+    if (temperature === symbol) return { kind: "temperature", symbol: temperature };
+  }
+  return undefined;
+}
+
+const TO_CELSIUS: Record<TemperatureSymbol, (value: number) => number> = {
+  C: (value) => value,
+  F: (value) => ((value - 32) * 5) / 9,
+  K: (value) => value - 273.15,
+};
+
+const FROM_CELSIUS: Record<TemperatureSymbol, (celsius: number) => number> = {
+  C: (celsius) => celsius,
+  F: (celsius) => (celsius * 9) / 5 + 32,
+  K: (celsius) => celsius + 273.15,
+};
+
+const ABSOLUTE_ZERO: Record<TemperatureSymbol, number> = { C: -273.15, F: -459.67, K: 0 };
+
+function convertTemperature(value: number, from: TemperatureSymbol, to: TemperatureSymbol): number {
+  if (value < ABSOLUTE_ZERO[from]) {
+    throw new RangeError(`temperature below absolute zero: ${value} ${from}`);
+  }
+  if (from === to) return value;
+  return FROM_CELSIUS[to](TO_CELSIUS[from](value));
+}
